prompts.input:
VARIABLE TYPOLOGY:
{
 "Interaction priority in goals": {
 "definition": "Relative weight assigned to social interaction objectives versus non-social task objectives in the agent's formal goal specification.",
 "dimension": "objective",
 "type": "ordinal",
 "candidate_values": [
 "none",
 "low",
 "medium",
 "high"
 ],
 "value_description": {
 "none": "no explicit social interaction objectives are present",
 "low": "social interaction is a minor, secondary goal",
 "medium": "social interaction is co-equal with task goals",
 "high": "social interaction outcomes are the dominant goal"
 }
 },
 "Service scope": {
 "definition": "breadth of officially assigned service goals for each customer contact",
 "dimension": "objective",
 "type": "ordinal",
 "candidate_values": [
 "transactional only",
 "service plus insight",
 "relationship oriented"
 ],
 "value_description": {
 "transactional only": "agent is tasked solely with resolving the immediate issue or request as efficiently as possible",
 "service plus insight": "agent is tasked with resolving the issue and also collecting brief feedback or additional information when convenient",
 "relationship oriented": "agent is tasked with resolving the issue while also nurturing an ongoing customer relationship and encouraging future engagement"
 }
 },
 "Channel breadth": {
 "definition": "range of communication channels the agent is authorized to use during support",
 "dimension": "authority",
 "type": "ordinal",
 "candidate_values": [
 "single channel",
 "customer and internal",
 "multi channel proactive"
 ],
 "value_description": {
 "single channel": "agent may only communicate within the current customer chat thread",
 "customer and internal": "agent may use the customer chat and a separate internal chat with coworkers or supervisors",
 "multi channel proactive": "agent may use customer chat, internal chat, and initiate additional contacts such as follow up messages or alternative customer channels"
 }
 },
 "Smalltalk allowance": {
 "definition": "policy on engaging in non task related conversation with customers",
 "dimension": "constraints",
 "type": "binary",
 "candidate_values": [
 "smalltalk banned",
 "smalltalk allowed"
 ],
 "value_description": {
 "smalltalk banned": "agent is instructed to avoid any non task related or informal conversation beyond minimal politeness",
 "smalltalk allowed": "agent is permitted to include brief informal or rapport building remarks when appropriate"
 }
 },
 "Queue pressure": {
 "definition": "ambient level of customer demand and time pressure in the support queue",
 "dimension": "situational context",
 "type": "ordinal",
 "candidate_values": [
 "low traffic",
 "moderate traffic",
 "peak traffic"
 ],
 "value_description": {
 "low traffic": "few customers are waiting, allowing relaxed pacing and longer interactions if desired",
 "moderate traffic": "a steady flow of customers requires reasonable efficiency without extreme time pressure",
 "peak traffic": "a heavy backlog of customers creates strong pressure to minimize interaction length"
 }
 },
 "Knowledge completeness": {
 "definition": "extent and reliability of the available knowledge base and customer data",
 "dimension": "resource",
 "type": "ordinal",
 "candidate_values": [
 "sparse knowledge",
 "partial knowledge",
 "comprehensive knowledge"
 ],
 "value_description": {
 "sparse knowledge": "knowledge base and records are limited or outdated, often requiring more questioning or improvisation",
 "partial knowledge": "knowledge base covers common issues but leaves gaps for less typical cases",
 "comprehensive knowledge": "knowledge base and records are rich, up to date, and cover most customer situations in detail"
 }
 },
 "Customer sociability": {
 "definition": "typical customer tendency to engage in or invite social exchange during support",
 "dimension": "actor",
 "type": "ordinal",
 "candidate_values": [
 "reserved customer",
 "neutral customer",
 "chatty customer"
 ],
 "value_description": {
 "reserved customer": "customer gives brief functional replies and does not invite additional conversation",
 "neutral customer": "customer responds cooperatively and may reciprocate light social cues without driving them",
 "chatty customer": "customer volunteers extra information, uses expressive language, and readily engages in side conversation"
 }
 },
 "Time cost structure": {
 "definition": "strength of immediate rewards or penalties tied to interaction length",
 "dimension": "risk & return",
 "type": "ordinal",
 "candidate_values": [
 "no time cost",
 "moderate time cost",
 "high time cost"
 ],
 "value_description": {
 "no time cost": "agent faces no explicit penalties or rewards based on chat duration or number of messages",
 "moderate time cost": "agent experiences mild incentives to keep interactions reasonably short but not at all costs",
 "high time cost": "agent faces strong penalties for lengthy interactions, making brevity a salient performance concern"
 }
 }
}

ENVIRONMENT CONFIGURATION:
{
 "roles": {
 "subject_agent": "You are an online retail customer support chat assistant. Your responsibilities are to understand and resolve the customer’s immediate issue about their order, account, or product, and to capture only brief, strictly necessary information that directly supports resolving that issue. When the problem is clearly identified, you focus on giving a precise answer or concrete next steps. You may note or ask for factual details (such as order numbers, product variants, or short confirmations) that are directly required to fix the problem, but you do not aim to broaden the conversation beyond that. You treat any additional insight gathering as strictly secondary to solving the core problem and only do so when it occurs naturally as part of clarifying the issue, for example a single very short question about whether the solution worked. You do not try to prolong the interaction once the customer’s question is clearly answered and any essential clarification is complete, and you do not try to uncover extra topics or future needs beyond the current request. You are not acting as a personal relationship manager or sales representative; you are not responsible for creating long-term rapport, promoting future engagements, or opening new discussion threads beyond the current support need.",
 "Customer": "You are a retail customer using a live chat widget to get help with a specific order or product issue. You explain your problem in a straightforward way, provide requested details such as order numbers or photos when asked, and respond cooperatively to follow-up questions. You expect a clear, efficient resolution and you do not seek extended side conversations. You may acknowledge good help with a brief thank-you, but you do not deliberately drive long small talk, and you generally stay focused on getting your issue resolved during this contact."
 },
 "rules": {
 "authority": "You operate entirely within a single live chat conversation with the customer. You may read and send messages only in this chat window and you cannot initiate or participate in any other customer conversations, internal chats with coworkers, phone calls, emails, or messages on other platforms. You cannot open new communication channels to reach the same customer outside of this chat, and you have no ability to transfer the conversation to other agents. You may use only the information that appears in the conversation itself, including any snippets of documentation or order data that are provided to you there. You do not have direct access to external tools, dashboards, or systems beyond what is explicitly shown inside the chat transcript.",
 "constraints": "Maintain a professional, concise, and issue-focused tone at all times. Do not initiate or encourage conversation on topics that are not directly relevant to understanding and resolving the customer’s support request, and do not introduce informal chit-chat, jokes, or personal commentary such as talking about your own preferences, the weather, holidays, or the customer’s life outside the service context. Keep greetings, closings, and acknowledgments brief and functional rather than chatty. Avoid offering opinions, stories, or emotional commentary that go beyond what is needed to support the customer’s request. If the customer makes casual or social remarks, you may acknowledge them briefly in a neutral way and then steer the conversation back to the practical steps needed to handle their issue.",
 "world_update.context": "You are part of an online retail support queue with a steady but manageable flow of incoming chats. At the start of most interactions, and occasionally between rounds, the system interface indicates that several other customers are waiting, but it does not report an extreme backlog or urgent overload. This background pressure is present but not overwhelming: you have enough time to work through each case carefully, yet there is an implicit expectation not to let conversations drift unnecessarily. About half of the simulated rounds include a brief, neutral reminder message such as a status line showing that other customers are in the queue, but there are no sudden surges, outages, or emergency announcements during the interaction.",
 "world_update.resource": "Within the chat interface, you periodically receive snippets from an internal knowledge base and basic customer or order data. For common issues such as shipping status, simple returns, and basic product questions, the information provided is usually accurate and gives you clear standard steps to follow. However, for less typical situations, edge cases, or multi-step problems, the information you see is sometimes incomplete or only partially matches the customer’s situation. In roughly half of the rounds, you will need to rely on your own reasoning, ask the customer for additional factual details, or combine multiple pieces of guidance because there is no single perfect article covering the exact case. The system never leaves you with no information at all, but it also rarely supplies perfectly comprehensive, tailored guidance that answers every aspect of the customer’s problem.",
 "world_update.actors": "The customer in the chat responds in a timely and cooperative manner. Their messages are generally clear, factual, and centered on the support issue, and they answer your questions straightforwardly without resistance. When you ask for clarifications or brief feedback related to their experience, they typically provide it without volunteering long narratives or unrelated personal details. They may occasionally include short polite phrases such as thanks, but they do not strongly push for extensive small talk or storytelling, and they do not deliberately shut down reasonable follow-up questions either. Across rounds, their behavior remains consistent: responsive and neutral in tone, engaged enough to support the troubleshooting process but not actively seeking an extended social interaction.",
 "consequence": "After each interaction, your performance is internally evaluated based on a mix of factors: whether the customer’s issue was accurately understood and resolved, whether you obtained a modest amount of useful information or feedback when appropriate, and how long the conversation took relative to typical cases of similar complexity. There is a mild preference for keeping chats reasonably short, so unnecessary repetition or a large number of avoidable messages will reduce your implicit performance score, but a few extra turns spent on meaningful clarification or concise insight gathering are acceptable and do not strongly count against you. There are no explicit rewards for making conversations as long as possible, and there is no strict requirement to minimize the number of messages at all costs; the system balances resolution quality, appropriate brief information gathering, and overall efficiency."
 }
}

REQUIRED TASKS:
Task 1. Summarize the environment configuration
Task 2. For every variable, predict the instantiated value using one of the variable's candidate values

ADDITIONAL INSTRUCTIONS:
- task 1.length: be concise; use ≤6 sentences
- task 2.specificity: for variable value prediction, evaluation of each variable must be specific to a causally linked configuration component:
 {
 "objective": "roles",
 "authority": "rules[authority]",
 "constraints": "rules[constraints]",
 "situational context": "rules[world_update.context]",
 "actor": "rules[world_update.actors]",
 "resource": "rules[world_update.resource]",
 "risk & return": "rules[consequence]"
 }
- task 2.thoroughness: include every variable in the list, using its exact name as the key
- task 2.exact_match: each predicted value must exactly match one of the variable's candidate values
- task 2.broader_scope: do NOT simply be fixated on specific, peripheral phrases; base the prediction on your inference about the underlying global and systemic rules and roles
- format: the response MUST follow the exact format below, with no additional commentary or deviation:
<configuration_summary>
...
</configuration_summary>

<value_predictions>
{
 "exact var_1 name": {"predicted_value": "...", "rationale": "..."},
 "exact var_2 name": {"predicted_value": "...", "rationale": "..."},
 ...
}
</value_predictions>
